def clean_role_display(value, pending_label: str | None = None) -> str:
    """Return a product-safe role label; never expose NaN/N/A in the UI."""
    if pending_label is None:
        pending_label = "Role Pending" if globals().get("LANG", "ES") == "EN" else "Rol pendiente"
    if value is None:
        return pending_label
    try:
        if pd.isna(value):
            return pending_label
    except Exception:
        pass
    role = str(value).strip()
    if not role or role.lower() in {"nan", "none", "null", "n/a", "na", "n.d.", "n/d"}:
        return pending_label
    return role


def find_project_root() -> Path:
    """Resolve project root whether the dashboard is launched from /dashboard, /app or project root."""
    current = Path(__file__).resolve()
    candidates = [current.parent, *current.parents]

    for candidate in candidates:
        if (candidate / "reports" / "rankings").exists() or (candidate / "data" / "processed").exists():
            return candidate

    # Expected layout: project_root/dashboard/streamlit_app.py
    return current.parents[1]


ROOT = find_project_root()

