def get_first_valid_numeric(row, columns, default=np.nan):
    """Return the first valid numeric value found in a row across candidate columns."""
    for col in columns:
        try:
            if col in row.index:
                value = pd.to_numeric(pd.Series([row[col]]), errors="coerce").iloc[0]
                if pd.notna(value):
                    return float(value)
        except Exception:
            continue
    return default


def format_age_metadata(row, lang: str = "ES") -> str:
    """Format age metadata safely for scouting cards.

    The Football Intelligence lookup can come from broader processed panels where
    age may be stored under a non-standard name or may be unavailable. This helper
    avoids rendering "nan años" and restores age when an alternate age column is
    present.
    """
    age_value = get_first_valid_numeric(
        row,
        [
            "age",
            "player_age",
            "age_years",
            "age_at_season",
            "age_latest",
            "tm_age",
            "transfermarkt_age",
        ],
    )
    if pd.notna(age_value):
        suffix = "years" if lang == "EN" else "años"
        return f"{age_value:.1f} {suffix}"
    return ""


def safe_get(row, col, default="N/A"):
    try:
        value = row[col]
        if pd.isna(value):
            return default
        col_name = str(col) if col is not None else ""
        # Single presentation rule: every visible club/team field is normalized
        # at access time, so cards, tooltips, rankings and tables never expose
        # legal entity names such as S.A.D., Football Club or Team Dubai.
        if col_name in globals().get("CLUB_DISPLAY_COLUMNS", []) or "club" in col_name.lower() or col_name.lower() in {"team", "squad"}:
            return format_club_name(value, fallback=default)
        return value
    except Exception:
        return default


