def _tm69_norm(value: object) -> str:
    try:
        return normalize_search_text(value)
    except Exception:
        return str(value).strip().lower()


def _tm69_find_matching_row(df: pd.DataFrame, base_row: pd.Series) -> dict:
    if df is None or df.empty:
        return {}
    base_id = None
    for col in ["player_id_tm", "player_id", "tm_player_id"]:
        if col in base_row.index and _tm69_is_valid(base_row[col]):
            base_id = str(base_row[col]).split(".")[0]
            break
    if base_id:
        for col in ["player_id_tm", "player_id", "tm_player_id", "identity_primary_key"]:
            if col in df.columns:
                try:
                    mask = df[col].astype(str).str.replace(r"\.0$", "", regex=True) == base_id
                    if bool(mask.any()):
                        return df.loc[mask].iloc[0].to_dict()
                except Exception:
                    pass
    base_names = []
    for col in ["player_name", "player_name_tm", "player_name_fbref", "Player", "player"]:
        if col in base_row.index and _tm69_is_valid(base_row[col]):
            base_names.append(_tm69_norm(base_row[col]))
    try:
        base_names.append(_tm69_norm(get_player_name(base_row)))
    except Exception:
        pass
    base_names = [n for n in dict.fromkeys(base_names) if n]
    if not base_names:
        return {}
    for col in ["player_name", "player_name_tm", "player_name_fbref", "Player", "player", "name", "player_name_norm"]:
        if col in df.columns:
            try:
                norm_series = df[col].fillna("").astype(str).map(_tm69_norm)
                mask = norm_series.isin(base_names)
                if bool(mask.any()):
                    return df.loc[mask].iloc[0].to_dict()
            except Exception:
                continue
    return {}


@st.cache_data(show_spinner=False)
def _tm69_v13b_identity_performance_lookup() -> dict:
    """Recover TM identity + advanced defensive fields for Player Intelligence."""
    try:
        path = ROOT / "data" / "processed" / "player_season_modeling_v13b_advanced.parquet"
        df = pd.read_parquet(path)
        keep = [
            "player_id_tm", "player_name_fbref", "player_name_tm",
            "date_of_birth", "foot", "height_in_cm",
            "adv_interceptions", "adv_tackles_won",
            "interceptions_position_pct", "tackles_won_position_pct",
            "defensive_activity_index",
            "position_tm", "sub_position_tm", "position_group", "position"
        ]
        keep = [c for c in keep if c in df.columns]
        df = df[keep].copy()

        if "player_id_tm" in df.columns:
            df["player_id_tm_key"] = pd.to_numeric(df["player_id_tm"], errors="coerce").astype("Int64")

        # Prefer latest/best row by defensive_activity_index and minutes proxy if available
        sort_cols = [c for c in ["defensive_activity_index", "interceptions_position_pct", "tackles_won_position_pct"] if c in df.columns]
        if sort_cols:
            df = df.sort_values(sort_cols, ascending=[False] * len(sort_cols))

        lookup = {}

        if "player_id_tm_key" in df.columns:
            by_id = df.dropna(subset=["player_id_tm_key"]).drop_duplicates("player_id_tm_key", keep="first")
            for _, r in by_id.iterrows():
                lookup[f"id::{int(r['player_id_tm_key'])}"] = r.to_dict()

        for name_col in ["player_name_fbref", "player_name_tm"]:
            if name_col in df.columns:
                tmp = df.dropna(subset=[name_col]).copy()
                tmp["player_key"] = tmp[name_col].astype(str).map(normalize_search_text)
                tmp = tmp.drop_duplicates("player_key", keep="first")
                for _, r in tmp.iterrows():
                    lookup[f"name::{r['player_key']}"] = r.to_dict()

        return lookup
    except Exception:
        return {}


def _tm69_merge_context(row: pd.Series) -> dict:
    ctx = dict(row.to_dict())

    for _, df in _tm69_load_context_tables().items():
        matched = _tm69_find_matching_row(df, row)
        for key, value in matched.items():
            if not _tm69_is_valid(ctx.get(key)) and _tm69_is_valid(value):
                ctx[key] = value
            else:
                ctx[f"tm69_{key}"] = value

    lookup = _tm69_v13b_identity_performance_lookup()
    enriched = {}

    try:
        player_id = ctx.get("player_id_tm")
        if player_id is not None and pd.notna(player_id):
            enriched = lookup.get(f"id::{int(float(player_id))}", {})
    except Exception:
        enriched = {}

    if not enriched:
        for name in [
            ctx.get("player_name_fbref"),
            ctx.get("player_name_tm"),
            ctx.get("player_name"),
            ctx.get("player"),
            ctx.get("name"),
        ]:
            key = normalize_search_text(name or "")
            if key:
                enriched = lookup.get(f"name::{key}", {})
                if enriched:
                    break

    for key, value in enriched.items():
        if _tm69_is_valid(value):
            ctx[key] = value
            ctx[f"tm69_{key}"] = value

    return ctx


def _tm69_initials(name: str, max_len: int = 2) -> str:
    parts = [p for p in re.split(r"\s+", str(name).strip()) if p]
    return "".join(p[0] for p in parts[:max_len]).upper() or "PI"


def _tm69_club_initials(club: str) -> str:
    cleaned = re.sub(r"\b(fc|cf|sc|afc|club|united|de|la|the)\b", "", str(club), flags=re.I).strip()
    return _tm69_initials(cleaned or club, 3)


def _tm69_format_date(value: object) -> str:
    if not _tm69_is_valid(value):
        return "N/A"
    try:
        return pd.to_datetime(value).strftime("%Y-%m-%d")
    except Exception:
        return str(value)


def _tm69_localize_foot(value: object) -> str:
    if not _tm69_is_valid(value):
        return "N/A"
    raw = str(value).strip().lower()
    is_en = globals().get("LANG") == "EN"
    mapping_en = {"right": "Right", "left": "Left", "both": "Both", "either": "Both"}
    mapping_es = {"right": "Diestro", "left": "Zurdo", "both": "Ambidiestro", "either": "Ambidiestro"}
    return (mapping_en if is_en else mapping_es).get(raw, str(value).strip().title())


def _tm69_localize_country(value: object) -> str:
    if not _tm69_is_valid(value):
        return "N/A"
    country = str(value).strip()
    if globals().get("LANG") == "EN":
        return country
    mapping = {
        "Spain": "España", "England": "Inglaterra", "Germany": "Alemania", "France": "Francia",
        "Italy": "Italia", "Portugal": "Portugal", "Netherlands": "Países Bajos", "Belgium": "Bélgica",
        "Austria": "Austria", "Denmark": "Dinamarca", "Sweden": "Suecia", "Norway": "Noruega",
        "Cote d'Ivoire": "Costa de Marfil", "Ivory Coast": "Costa de Marfil", "Brazil": "Brasil",
        "Argentina": "Argentina", "Uruguay": "Uruguay", "Morocco": "Marruecos", "Croatia": "Croacia",
        "United States": "Estados Unidos", "USA": "Estados Unidos",
        "Nigeria": "Nigeria", "Georgia": "Georgia", "Mali": "Mali", "Senegal": "Senegal",
        "Ghana": "Ghana", "Serbia": "Serbia", "Poland": "Polonia", "Switzerland": "Suiza",
        "Japan": "Japón", "South Korea": "Corea del Sur", "Mexico": "México",
        "Colombia": "Colombia", "Cote d Ivoire": "Costa de Marfil",
    }
    return mapping.get(country, country)


def _tm69_localize_contract_status(value: object) -> str:
    if not _tm69_is_valid(value):
        return "N/A"
    raw = str(value).strip()
    if globals().get("LANG") == "EN":
        return raw.replace("_", " ").title()
    norm = raw.strip().lower().replace("_", " ")
    mapping = {
        "protected asset": "Activo protegido",
        "protected": "Protegido",
        "critical zone": "Zona crítica",
        "expiring": "Próximo a expirar",
        "free agent": "Libre",
        "short term": "Corto plazo",
        "medium term": "Medio plazo",
        "long term": "Largo plazo",
    }
    return mapping.get(norm, raw.replace("_", " ").title())


def _tm69_role_quality_label(ctx: dict, role_value: float) -> tuple[str, str]:
    is_en = globals().get("LANG") == "EN"
    has_purity = any(_tm69_is_valid(ctx.get(k)) for k in ["role_purity", "tm69_role_purity", "primary_role_similarity", "tm69_primary_role_similarity"])
    if has_purity:
        if pd.isna(role_value):
            quality = "Pending" if is_en else "Pendiente"
        elif role_value < 35:
            quality = "High hybrid profile" if is_en else "Perfil híbrido alto"
        elif role_value < 65:
            quality = "Mixed role profile" if is_en else "Perfil mixto"
        else:
            quality = "Specialised profile" if is_en else "Perfil especializado"
        return ("Role purity" if is_en else "Pureza de rol", quality)
    return ("Role confidence" if is_en else "Confianza de rol", "")


def _tm69_escape_rich_text(text: str) -> str:
    # allow only intentional <b> tags in executive recommendation text
    escaped = html.escape(text)
    return escaped.replace("&lt;b&gt;", "<b>").replace("&lt;/b&gt;", "</b>")


def _tm69_age_from_birth(value: object, fallback: object = np.nan) -> float:
    try:
        fallback_num = pd.to_numeric(pd.Series([fallback]), errors="coerce").iloc[0]
        if pd.notna(fallback_num):
            return float(fallback_num)
    except Exception:
        pass
    try:
        birth = pd.to_datetime(value)
        today = pd.Timestamp.today(tz=None)
        return float((today - birth).days / 365.25)
    except Exception:
        return np.nan


def _tm69_position_code(value: object) -> str:
    raw = str(value).strip()
    if not raw or raw.lower() in {"nan", "none", "n/a"}:
        return ""
    norm = raw.lower().replace("-", " ").replace("_", " ")
    mapping = [
        ("goalkeeper", "GK"), ("keeper", "GK"),
        ("right back", "RB"), ("left back", "LB"), ("full back", "FB"),
        ("centre back", "CB"), ("center back", "CB"), ("central defender", "CB"),
        ("defensive midfield", "DM"), ("central midfield", "CM"), ("attacking midfield", "AM"),
        ("right winger", "RW"), ("left winger", "LW"), ("winger", "W"),
        ("centre forward", "CF"), ("center forward", "CF"), ("second striker", "SS"), ("striker", "CF"),
    ]
    for token, code in mapping:
        if token in norm:
            return code
    upper = raw.upper().strip()
    if upper in {"GK", "CB", "RB", "LB", "FB", "WB", "DM", "CM", "AM", "RW", "LW", "W", "CF", "ST", "SS", "ATT", "MID", "DEF"}:
        return "CF" if upper == "ST" else upper
    return upper[:3]


def _tm69_position_set(ctx: dict) -> tuple[str, list[str]]:
    primary = _tm69_position_code(_tm69_first(ctx, ["sub_position_tm", "sub_position", "position_tm", "position_taxonomy", "position", "position_group"], ""))
    secondary_raw = str(_tm69_first(ctx, ["position_tm", "position", "sub_position_tm", "sub_position"], ""))
    candidates = []
    for part in re.split(r"[,;/|]+", secondary_raw):
        code = _tm69_position_code(part)
        if code and code != primary:
            candidates.append(code)
    if not candidates and primary in {"RW", "LW", "W"}:
        candidates = ["LW" if primary == "RW" else "RW", "AM"]
    if not candidates and primary in {"CM", "DM", "AM"}:
        candidates = [c for c in ["CM", "DM", "AM"] if c != primary]
    if not primary:
        primary = "N/A"
    return primary, list(dict.fromkeys(candidates))[:3]


def _tm69_position_marker_keys(code: str) -> set[str]:
    """Map Scouting IQ taxonomy to a 4-3-3 positional board.

    The field uses professional scouting labels rather than generic model labels:
    POR; LI/CTI/CTD/LD; MC/MCO/MC; EI/DC/ED. When the data only exposes a broad
    taxonomy (for instance CB or DEF), the marker highlights the natural zone(s)
    instead of inventing a left/right side.
    """
    code = str(code or "").upper().strip()
    mapping = {
        "GK": {"GK"}, "POR": {"GK"},
        "LB": {"LB"}, "LI": {"LB"},
        "RB": {"RB"}, "LD": {"RB"},
        "FB": {"LB", "RB"}, "WB": {"LB", "RB"},
        "CB": {"LCB", "RCB"}, "DEF": {"LCB", "RCB"},
        "DM": {"DM"},
        "CM": {"LCM", "RCM"}, "MID": {"LCM", "RCM"},
        "AM": {"AM"},
        "LW": {"LW"}, "EI": {"LW"},
        "RW": {"RW"}, "ED": {"RW"},
        "W": {"LW", "RW"},
        "CF": {"CF"}, "ST": {"CF"}, "DC": {"CF"}, "ATT": {"CF"}, "FWD": {"CF"}, "FW": {"CF"},
    }
    return mapping.get(code, set())


def _tm69_position_markers(primary: str, secondary: list[str]) -> str:
    """Render a 4-3-3 tactical board with real 105x68 pitch proportions."""
    is_en = globals().get("LANG") == "EN"
    # x/y use a horizontal 105x68 pitch: own goal left, attacking goal right.
    slots = [
        ("GK", 7, 50, "GK" if is_en else "POR"),
        ("LB", 22, 20, "LB" if is_en else "LI"),
        ("LCB", 22, 41, "LCB" if is_en else "CTI"),
        ("RCB", 22, 59, "RCB" if is_en else "CTD"),
        ("RB", 22, 80, "RB" if is_en else "LD"),
        ("LCM", 50, 35, "CM" if is_en else "MC"),
        ("AM", 61, 50, "AM" if is_en else "MCO"),
        ("RCM", 50, 65, "CM" if is_en else "MC"),
        ("LW", 80, 20, "LW" if is_en else "EI"),
        ("CF", 90, 50, "ST" if is_en else "DC"),
        ("RW", 80, 80, "RW" if is_en else "ED"),
    ]
    primary_keys = _tm69_position_marker_keys(primary)
    secondary_keys: set[str] = set()
    for sec in secondary or []:
        secondary_keys |= _tm69_position_marker_keys(sec)
    secondary_keys -= primary_keys

    rows = []
    for key, x, y, label in slots:
        css = "primary" if key in primary_keys else ("secondary" if key in secondary_keys else "")
        title = "Dominant" if (is_en and key in primary_keys) else ("Dominante" if key in primary_keys else ("Secondary" if is_en else "Secundaria"))
        rows.append(
            f"<div class='exec-pos-marker {css}' data-slot='{html.escape(key)}' title='{html.escape(title)}' style='left:{x}%;top:{y}%;'>{html.escape(label)}</div>"
        )
    return "".join(rows)

def _tm69_signal_title(metric: str) -> str:
    is_en = globals().get("LANG") == "EN"
    labels = {
        "opportunity": ("Opportunity", "Oportunidad"),
        "growth": ("Growth", "Crecimiento"),
        "risk": ("Risk", "Riesgo"),
        "contract": ("Contract", "Contrato"),
    }
    en, es = labels.get(metric, (metric.title(), metric.title()))
    return en if is_en else es


def _tm69_signal_card(label: str, value: float, metric: str, accent: str, soft: str, dark: str) -> str:
    safe_label = html.escape(label)
    safe_value = html.escape(_tm69_format_score(value))
    safe_status = html.escape(_tm69_score_label(metric, value))
    return (
        f"<div class='exec-signal-card' style='--accent:{accent};--soft:{soft};--dark:{dark};'>"
        f"<div class='exec-signal-label'>{safe_label}</div>"
        f"<div class='exec-signal-value'>{safe_value}</div>"
        f"<div class='exec-signal-status'>{safe_status}</div>"
        f"</div>"
    )



def _tm69_target_priority_score(opportunity: float, growth: float, risk: float, contract: float) -> float:
    """UI-only executive composite for the card; it does not alter DSS scoring or model outputs."""
    components: list[tuple[float, float]] = []
    if pd.notna(opportunity):
        components.append((0.45, float(opportunity)))
    if pd.notna(growth):
        components.append((0.25, float(growth)))
    if pd.notna(risk):
        components.append((0.20, 100.0 - float(risk)))
    if pd.notna(contract):
        components.append((0.10, float(contract)))
    if not components:
        return np.nan
    total_w = sum(w for w, _ in components)
    return max(0.0, min(100.0, sum(w * v for w, v in components) / total_w))


def _tm69_target_priority_grade(score: float) -> str:
    if pd.isna(score):
        return "—"
    if score >= 90:
        return "A+"
    if score >= 82:
        return "A"
    if score >= 74:
        return "B+"
    if score >= 65:
        return "B"
    if score >= 55:
        return "C"
    return "D"

def _tm69_scale_role_metric(value: object) -> float:
    """Normalize role/DNA artefacts to a 0-100 product scale."""
    num = pd.to_numeric(pd.Series([value]), errors="coerce").iloc[0]
    if pd.isna(num):
        return np.nan
    num = float(num)

    # Role artefacts may be z-like, 0-1, or already 0-100.
    if -3 <= num <= 3:
        return float(np.clip(50 + num * 16.7, 0, 100))
    if 0 <= num <= 1:
        return float(np.clip(num * 100, 0, 100))
    return float(np.clip(num, 0, 100))


def _tm69_is_defensive_profile(ctx: dict) -> bool:
    """Detect centre-back/defensive profiles to avoid offensive-led Role DNA narratives."""
    role_raw = _tm69_first(ctx, ["primary_role", "role_subgroup", "tm69_role_subgroup", "taxonomy_role_context"], "")
    pos_raw = _tm69_first(ctx, ["position_group", "position", "pos_", "tm69_position_group"], "")

    role_key = normalize_join_text(role_raw) if "normalize_join_text" in globals() else str(role_raw).lower()
    pos_key = normalize_join_text(pos_raw) if "normalize_join_text" in globals() else str(pos_raw).lower()

    defensive_roles = {
        "ball playing centre back",
        "aerial defender",
        "aggressive defender",
        "defensive anchor",
        "ball winner",
        "def cb",
        "defender",
        "centre back",
        "center back",
    }

    return (
        pos_key in {"def", "cb", "dc", "def cb", "defender"}
        or "centre back" in role_key
        or "center back" in role_key
        or role_key in defensive_roles
        or str(role_raw).upper() in {"DEF_CB", "CB"}
    )




def _tm69_dna_values(ctx: dict) -> list[tuple[str, float]]:
    """
    Position-aware tactical DNA for TM.6.9 Player Intelligence.

    Values describe relative tactical contribution inside the detected role.
    They are not absolute performance grades or global percentiles.
    """
    is_en = globals().get("LANG") == "EN"
    is_defensive = _tm69_is_defensive_profile(ctx)

    creation = _tm69_scale_role_metric(_tm69_numeric(ctx, [
        "creation_index_role",
        "chance_creation_index",
        "tm69_creation_index_role",
        "tm69_chance_creation_index",
    ]))
    progression = _tm69_scale_role_metric(_tm69_numeric(ctx, [
        "progression_index_role",
        "ball_progression_index",
        "tm69_progression_index_role",
        "tm69_ball_progression_index",
    ]))
    finishing = _tm69_scale_role_metric(_tm69_numeric(ctx, [
        "finishing_index_role",
        "tm69_finishing_index_role",
    ]))
    defending = _tm69_scale_role_metric(_tm69_numeric(ctx, [
        "defending_index_role",
        "defensive_activity_index",
        "tm69_defensive_activity_index",
        "interceptions_position_pct",
        "tm69_interceptions_position_pct",
        "tm69_defending_index_role",
    ]))
    duels = _tm69_scale_role_metric(_tm69_numeric(ctx, [
        "duel_index_role",
        "tackles_won_position_pct",
        "tm69_tackles_won_position_pct",
        "aerial_duels_won_pct",
        "tm69_aerial_duels_won_pct",
        "tm69_duel_index_role",
    ]))

    if is_defensive:
        finishing_secondary = np.nan if pd.isna(finishing) else min(finishing, 45.0)
        items = [
            ("Progression" if is_en else "Progresión", progression),
            ("Defending" if is_en else "Defensa", defending),
            ("Duels" if is_en else "Duelos", duels),
            ("Creation" if is_en else "Creación", creation),
            ("Secondary finishing" if is_en else "Finalización secundaria", finishing_secondary),
        ]
    else:
        items = [
            ("Creation" if is_en else "Creación", creation),
            ("Progression" if is_en else "Progresión", progression),
            ("Finishing" if is_en else "Finalización", finishing),
            ("Defending" if is_en else "Defensa", defending),
            ("Duels" if is_en else "Duelos", duels),
        ]

    return [(label, value) for label, value in items if pd.notna(value)]

