def opportunity_tier_badge(value) -> str:
    score = pd.to_numeric(pd.Series([value]), errors="coerce").iloc[0]
    if pd.isna(score):
        label, cls = ("N/D" if globals().get("LANG", "ES") == "ES" else "N/A"), "neutral"
    elif float(score) >= 85:
        label, cls = "Elite", "success"
    elif float(score) >= 70:
        label, cls = ("High" if globals().get("LANG", "ES") == "EN" else "Alta"), "primary"
    elif float(score) >= 50:
        label, cls = ("Watch" if globals().get("LANG", "ES") == "EN" else "Seguimiento"), "warning"
    else:
        label, cls = ("Low" if globals().get("LANG", "ES") == "EN" else "Baja"), "neutral"
    return f"<span class='exec-mini-badge exec-mini-badge-{cls}'>{html.escape(label)} <b>{format_score(score)}</b></span>"


def risk_tier_badge(value) -> str:
    score = pd.to_numeric(pd.Series([value]), errors="coerce").iloc[0]
    if pd.isna(score):
        label, cls = ("N/D" if globals().get("LANG", "ES") == "ES" else "N/A"), "neutral"
    elif float(score) <= 20:
        label, cls = ("Low" if globals().get("LANG", "ES") == "EN" else "Bajo"), "success"
    elif float(score) <= 45:
        label, cls = ("Moderate" if globals().get("LANG", "ES") == "EN" else "Moderado"), "warning"
    else:
        label, cls = ("High" if globals().get("LANG", "ES") == "EN" else "Alto"), "danger"
    return f"<span class='exec-mini-badge exec-mini-badge-{cls}'>{html.escape(label)} <b>{format_score(score)}</b></span>"


def decision_stars_badge(value) -> str:
    score = pd.to_numeric(pd.Series([value]), errors="coerce").iloc[0]
    if pd.isna(score):
        return "<span class='exec-mini-badge exec-mini-badge-neutral'>—</span>"
    stars = max(1, min(5, int(np.ceil(float(score) / 20))))
    return f"<span class='decision-stars' title='Decision Score {format_score(score)}'>{'★' * stars}{'☆' * (5 - stars)} <b>{format_score(score)}</b></span>"


def build_html_table(page_df: pd.DataFrame):
    """Build a compact recruitment-board table for the main view.

    The main dashboard should behave like an executive board: few columns,
    clear actions and no methodological clutter. Detailed variables remain in
    the specialised modules and CSV exports.
    """
    columns = [
        ("player_name_fbref", "Player" if LANG == "EN" else "Jugador"),
        ("primary_role", "Role" if LANG == "EN" else "Rol"),
        ("club", "Club"),
        ("league", T("league")),
        ("position_group", "Pos."),
        ("age", "Age" if LANG == "EN" else "Edad"),
        ("market_value_eur", "Value" if LANG == "EN" else "Valor"),
        ("projected_market_value_3y_eur", "Value 3Y" if LANG == "EN" else "Valor 3Y"),
        ("asset_roi_3y_pct", "ROI 3Y"),
        ("executive_decision_score_v2", "Decision"),
        ("opportunity_score", "Opportunity"),
        ("risk_score", "Risk"),
        ("recommended_action", "Action" if LANG == "EN" else "Acción"),
    ]
    columns = [(c, label) for c, label in columns if c in page_df.columns]

    header = "".join(f"<th>{html.escape(label)}</th>" for _, label in columns)
    rows = ""

    for _, r in page_df.iterrows():
        cells = []
        for col, _ in columns:
            val = safe_get(r, col, "")

            if col in {"market_value_eur", "projected_market_value_3y_eur"}:
                val = format_money_short(val)
            elif col == "asset_roi_3y_pct":
                try:
                    val = f"{float(val):.0f}%"
                except Exception:
                    val = "N/A"
            elif col in {"executive_decision_score_v2", "opportunity_score", "risk_score"}:
                val = format_score(val)
            elif col == "age":
                try:
                    val = f"{float(val):.1f}"
                except Exception:
                    val = "N/A"
            elif col == "club":
                val = f"{_tm69_club_mark_html(dict(r), str(val))} {html.escape(str(val))}"
                cells.append(f"<td>{val}</td>")
                continue
            elif col == "league":
                val = _tm69_league_chip_html(league_display_name(val))
                cells.append(f"<td>{val}</td>")
                continue
            elif col == "recommended_action":
                cells.append(f"<td>{recommendation_badge(str(val))}</td>")
                continue
            elif col == "primary_role":
                role_text = clean_role_display(val)
                role_cls = "role-badge role-badge-pending" if role_text in {"Role Pending", "Rol pendiente"} else "role-badge"
                icon = "⚪" if "pending" in role_text.lower() or "pendiente" in role_text.lower() else "🧠"
                cells.append(f"<td><span class='{role_cls}' style='margin-left:0;'>{icon} {html.escape(role_text)}</span></td>")
                continue

            if col == "executive_decision_score_v2":
                cells.append(f"<td>{decision_stars_badge(val)}</td>")
            elif col == "opportunity_score":
                cells.append(f"<td>{opportunity_tier_badge(val)}</td>")
            elif col == "risk_score":
                cells.append(f"<td>{risk_tier_badge(val)}</td>")
            else:
                cells.append(f"<td>{html.escape(str(val))}</td>")

        rows += "<tr>" + "".join(cells) + "</tr>"

    return f"""
    <div class="comparison-table-wrapper">
        <table class="player-table">
            <thead><tr>{header}</tr></thead>
            <tbody>{rows}</tbody>
        </table>
    </div>
    """

def make_shap_proxy(player_df: pd.Series) -> pd.DataFrame:
    minutes = float(safe_get(player_df, "minutes_played", 0))
    growth = float(safe_get(player_df, "growth_score", 50))
    opportunity = float(safe_get(player_df, "opportunity_score", 50))
    confidence = float(safe_get(player_df, "confidence_score", 50))
    age = float(safe_get(player_df, "age", 22))

    shap_values = pd.DataFrame(
        {
            "feature": [
                "Minutos jugados",
                "Goles por 90",
                "Asistencias por 90",
                "Growth Score",
                "Confidence Score",
                "Edad",
                T("league"),
                T("position"),
            ],
            "impact": [
                min(minutes / 2300, 1.35),
                min(opportunity / 140, 0.85),
                min(growth / 180, 0.70),
                min(growth / 160, 0.75),
                min(confidence / 220, 0.55),
                -0.22 if age > 22 else 0.15,
                0.18,
                -0.12,
            ],
        }
    )
    return shap_values.sort_values("impact")


