# =============================================================================
# TM.6.9 command search helpers — current identity, club normalisation and context
# =============================================================================
def _first_valid_command_value(row, cols, default=""):
    """Return first non-empty value across candidate row columns."""
    try:
        idx = row.index
    except Exception:
        return default
    for col in cols:
        if not col or col not in idx:
            continue
        value = row.get(col)
        try:
            if pd.isna(value):
                continue
        except Exception:
            pass
        value = str(value).strip()
        if value and value.lower() not in {"nan", "none", "null", "n/a", "n/d", "-"}:
            return value
    return default


def _command_row_context(df, raw):
    """Resolve product-safe current context for command search and ranking."""
    try:
        if df is None or getattr(df, "empty", True):
            return {}
        q = str(raw).strip()
        if not q:
            return {}
        name_col = get_player_name_column(df) if "get_player_name_column" in globals() else None
        mask = pd.Series(False, index=df.index)
        if "player_id_tm" in df.columns and q.replace(".0", "").isdigit():
            mask = mask | df["player_id_tm"].astype(str).str.replace(".0", "", regex=False).eq(q.replace(".0", ""))
        if name_col is not None and name_col in df.columns:
            mask = mask | df[name_col].astype(str).str.casefold().eq(q.casefold())
        if not mask.any() and name_col is not None and name_col in df.columns:
            mask = df[name_col].astype(str).str.casefold().str.contains(q.casefold(), na=False, regex=False)
        hit = df.loc[mask].copy()
        if hit.empty:
            return {}
        for sort_col in ["current_valuation_date", "valuation_date", "current_season", "season", "opportunity_score"]:
            if sort_col in hit.columns:
                hit = hit.sort_values(sort_col, ascending=False, na_position="last")
                break
        row = hit.iloc[0]
        club_raw = _first_valid_command_value(row, ["display_club", "current_club", "current_club_snapshot", "current_club_name_tm", "club_actual", "club"], "")
        league_raw = _first_valid_command_value(row, ["display_league", "current_league", "current_league_snapshot", "league"], "")
        return {
            "name": _first_valid_command_value(row, ["player_name_tm", "player_name_tm_snapshot", "player_name_fbref", name_col], q),
            "club": format_club_name(club_raw, "") if "format_club_name" in globals() else club_raw,
            "league": league_display_name(league_raw) if "league_display_name" in globals() else league_raw,
            "position": _first_valid_command_value(row, ["position_group", "position", "role_subgroup"], ""),
            "age": pd.to_numeric(row.get("age", row.get("current_age", np.nan)), errors="coerce"),
            "opportunity": pd.to_numeric(row.get("opportunity_score", np.nan), errors="coerce"),
            "risk": pd.to_numeric(row.get("risk_score", row.get("risk_adjusted_opportunity_score", np.nan)), errors="coerce"),
            "contract": pd.to_numeric(row.get("contract_opportunity_score", row.get("recruitment_contract_score", np.nan)), errors="coerce"),
            "growth": pd.to_numeric(row.get("growth_score", row.get("growth_index", np.nan)), errors="coerce"),
            "market_value": pd.to_numeric(row.get("market_value_eur", row.get("current_market_value_eur", np.nan)), errors="coerce"),
            "fair_value": pd.to_numeric(row.get("predicted_market_value_ml_eur", row.get("predicted_market_value_eur", np.nan)), errors="coerce"),
            "gap_pct": pd.to_numeric(row.get("market_value_gap_pct", np.nan), errors="coerce"),
            "gap_eur": pd.to_numeric(row.get("market_value_gap_eur", np.nan), errors="coerce"),
            "rank": pd.to_numeric(row.get("opportunity_rank", row.get("visual_rank", np.nan)), errors="coerce"),
            "action": str(row.get("recommended_action", row.get("action", "")) or ""),
        }
    except Exception:
        return {}

@st.cache_data(show_spinner=False)
def build_search_options(df: pd.DataFrame) -> tuple[list[str], dict[str, str]]:
    """Build global search options with clean product labels.

    Product rules:
    - one visible option per current player identity;
    - one visible command per league / position / role / club;
    - player labels always use product-normalised club names;
    - raw value for players remains the player name, preserving existing filters.
    """
    labels: list[str] = []
    label_to_raw: dict[str, str] = {}
    seen_labels: set[str] = set()
    seen_players: set[str] = set()
    seen_entities: set[tuple[str, str]] = set()

    def clean_key(value: object) -> str:
        return strip_accents_for_display(str(value)).lower().strip()

    def valid(value: object) -> bool:
        return str(value).strip().lower() not in {"", "nan", "none", "null", "n/a", "n/d", "-"}

    def add(label: str, raw: object, entity: str = "other") -> None:
        label = str(label).strip()
        raw = str(raw).strip()
        if not label or not valid(raw):
            return
        if entity in {"league", "club", "position", "role"}:
            entity_key = (entity, clean_key(raw))
            if entity_key in seen_entities:
                return
            seen_entities.add(entity_key)
        label_key = clean_key(label)
        if label_key in seen_labels:
            return
        seen_labels.add(label_key)
        labels.append(label)
        label_to_raw[label] = raw

    def first_existing(cols: list[str]) -> str | None:
        for c in cols:
            if c in df.columns:
                return c
        return None

    work = df.copy()

    if "player_id_tm" in work.columns:
        sort_cols = [c for c in ["current_valuation_date", "valuation_date", "current_season", "season", "opportunity_score"] if c in work.columns]
        if sort_cols:
            work = work.sort_values(sort_cols, ascending=[False] * len(sort_cols), na_position="last")
        work = work.drop_duplicates(subset=["player_id_tm"], keep="first").copy()

    # 1) Players first: label carries current, product-safe context.
    name_col = get_player_name_column(work)
    if name_col is not None:
        tmp = work.dropna(subset=[name_col]).copy()
        if "opportunity_score" in tmp.columns:
            tmp = tmp.sort_values("opportunity_score", ascending=False, na_position="last")
        elif "executive_decision_score_v2" in tmp.columns:
            tmp = tmp.sort_values("executive_decision_score_v2", ascending=False, na_position="last")

        for _, row in tmp.iterrows():
            name = _first_valid_command_value(row, ["player_name_tm", "player_name_tm_snapshot", "player_name_fbref", name_col], "")
            if not valid(name):
                continue
            player_key = (
                str(row.get("player_id_tm")).replace(".0", "")
                if "player_id_tm" in row.index and pd.notna(row.get("player_id_tm"))
                else clean_key(name)
            )
            if player_key in seen_players:
                continue
            seen_players.add(player_key)

            position = _first_valid_command_value(row, ["position_group", "position", "role_subgroup"], "")
            club_raw = _first_valid_command_value(row, ["display_club", "current_club", "current_club_snapshot", "current_club_name_tm", "club_actual", "club"], "")
            club = format_club_name(club_raw, "") if valid(club_raw) else ""
            league_raw = _first_valid_command_value(row, ["display_league", "current_league", "current_league_snapshot", "league"], "")
            league = league_display_name(league_raw) if valid(league_raw) else ""

            meta = " · ".join([str(x) for x in [position, club, league] if valid(x)])
            add(f"Player · {name}" + (f" · {meta}" if meta else ""), name, "player")

    # 2) League commands: one visible option per league.
    league_col = first_existing(["display_league", "current_league", "current_league_snapshot", "league"])
    if league_col is not None:
        league_values = sorted(work[league_col].dropna().astype(str).unique().tolist(), key=str.lower)
        for league in league_values:
            display = league_display_name(league)
            add(f"Liga · {display}" if LANG != "EN" else f"League · {display}", league, "league")

    # 3) Position commands.
    if "position_group" in work.columns:
        for pos in sorted(work["position_group"].dropna().astype(str).unique().tolist(), key=str.lower):
            add(f"Posición · {pos}" if LANG != "EN" else f"Position · {pos}", pos, "position")

    # 4) Role commands.
    role_cols = ["taxonomy_role_context", "role_context", "role_display", "role_subgroup", "position_role", "tactical_role"]
    for role_col in role_cols:
        if role_col in work.columns:
            for role in sorted(work[role_col].dropna().astype(str).unique().tolist(), key=str.lower):
                if valid(role):
                    add(f"Rol · {role}" if LANG != "EN" else f"Role · {role}", role, "role")

    # 5) Club commands: one visible option per product-normalised club.
    club_col = first_existing(["display_club", "current_club", "current_club_snapshot", "current_club_name_tm", "club_actual", "club"])
    if club_col is not None:
        normalised_clubs = sorted({format_club_name(c, "") for c in work[club_col].dropna().astype(str).tolist() if valid(c)}, key=str.lower)
        for club in normalised_clubs:
            add(f"Club · {club}", club, "club")

    return labels, label_to_raw


def _command_entity_type(label: str) -> str:
    clean = str(label).strip()
    low = clean.lower()
    if low.startswith(("player ·", "jugador ·")) or " · player" in low or " · jugador" in low:
        return "player"
    if low.startswith(("league ·", "liga ·")) or " · league" in low or " · liga" in low:
        return "league"
    if low.startswith(("club ·",)) or " · club" in low:
        return "club"
    if low.startswith(("position ·", "posición ·", "posicion ·")) or " · position" in low or " · posición" in low or " · posicion" in low:
        return "position"
    if low.startswith(("role ·", "rol ·")) or " · role" in low or " · rol" in low:
        return "role"
    return "other"



def _format_command_pct(value) -> str:
    """Format percentage safely for global command search."""
    try:
        if value is None:
            return "—"
        v = float(value)
        if abs(v) <= 1:
            v *= 100
        return f"{v:.1f}%"
    except Exception:
        return "—"


def rank_global_command_search(
    scoring_df: pd.DataFrame,
    query: str,
    search_options: list[str],
    label_to_raw: dict[str, str],
    max_results: int = 6,
) -> pd.DataFrame:
    """Hybrid DSS command search: fuzzy retrieval + Opportunity/Risk/Contract ranking."""
    q_norm = normalize_search_text(query)
    cols = [
        "label", "raw", "entity_type", "similarity", "opportunity", "risk", "contract", "growth",
        "market_value", "fair_value", "gap_pct", "gap_eur", "rank", "action", "typeahead_score",
        "club", "league", "position", "age"
    ]
    if not q_norm:
        return pd.DataFrame(columns=cols)

    rows = []
    seen = set()
    for label in search_options:
        raw = label_to_raw.get(label, label)
        entity_type = _command_entity_type(label)
        dedupe_key = (entity_type, normalize_search_text(raw))
        if dedupe_key in seen:
            continue
        seen.add(dedupe_key)
        label_norm = normalize_search_text(label)
        raw_norm = normalize_search_text(raw)
        if not label_norm and not raw_norm:
            continue
        label_sim = difflib.SequenceMatcher(None, q_norm, label_norm).ratio()
        raw_sim = difflib.SequenceMatcher(None, q_norm, raw_norm).ratio()
        contains_boost = 1.0 if (q_norm in label_norm or q_norm in raw_norm) else 0.0
        token_boost = 0.0
        q_tokens = [t for t in q_norm.split() if len(t) >= 2]
        if q_tokens:
            token_hits = sum(1 for t in q_tokens if t in label_norm or t in raw_norm)
            token_boost = token_hits / max(len(q_tokens), 1)
        text_similarity = max(label_sim, raw_sim, contains_boost, token_boost) * 100.0
        if text_similarity < 34 and contains_boost == 0 and token_boost < 0.5:
            continue

        ctx = _command_row_context(scoring_df, raw) if entity_type == "player" else {
            "club": "", "league": "", "position": "", "age": np.nan, "opportunity": np.nan, "risk": np.nan,
            "contract": np.nan, "growth": np.nan, "market_value": np.nan, "fair_value": np.nan,
            "gap_pct": np.nan, "gap_eur": np.nan, "rank": np.nan, "action": "",
        }
        opportunity = float(ctx.get("opportunity", np.nan)) if pd.notna(ctx.get("opportunity", np.nan)) else (55.0 if entity_type == "player" else 42.0)
        risk = float(ctx.get("risk", np.nan)) if pd.notna(ctx.get("risk", np.nan)) else (50.0 if entity_type == "player" else 55.0)
        contract = float(ctx.get("contract", np.nan)) if pd.notna(ctx.get("contract", np.nan)) else 50.0
        entity_boost = 5.0 if entity_type == "player" else (2.0 if entity_type in {"club", "league", "position", "role"} else 0.0)
        # Ranking de búsqueda: texto + señal deportiva/económica. Risk bajo suma.
        typeahead_score = (0.45 * text_similarity) + (0.35 * opportunity) + (0.20 * (100.0 - risk)) + entity_boost
        rows.append({
            "label": label,
            "raw": raw,
            "entity_type": entity_type,
            "similarity": round(text_similarity, 1),
            "opportunity": round(opportunity, 1),
            "risk": round(risk, 1),
            "contract": round(contract, 1) if pd.notna(contract) else np.nan,
            "growth": ctx.get("growth", np.nan),
            "market_value": ctx.get("market_value", np.nan),
            "fair_value": ctx.get("fair_value", np.nan),
            "gap_pct": ctx.get("gap_pct", np.nan),
            "gap_eur": ctx.get("gap_eur", np.nan),
            "rank": ctx.get("rank", np.nan),
            "action": ctx.get("action", ""),
            "typeahead_score": round(typeahead_score, 1),
            "club": ctx.get("club", ""),
            "league": ctx.get("league", ""),
            "position": ctx.get("position", ""),
            "age": ctx.get("age", np.nan),
        })

    ranked = pd.DataFrame(rows)
    if ranked.empty:
        return pd.DataFrame(columns=cols)
    ranked = ranked.sort_values(["typeahead_score", "similarity"], ascending=False).drop_duplicates(subset=["entity_type", "raw"]).head(max_results)
    return ranked.reset_index(drop=True)


def _command_set_player_context(player_name: str, destination: str | None = None) -> None:
    """Set common session selectors used across Player/Recruitment/Contract modules."""
    st.session_state["selected_player"] = player_name
    st.session_state["contract_selected_player"] = player_name
    st.session_state["contract_focus_player"] = player_name
    st.session_state["player_intelligence_report_selector"] = player_name
    st.session_state["radar_selected_player"] = player_name
    st.session_state["sprint11_similarity_target"] = player_name
    st.session_state["sprint11_replacement_target"] = player_name
    st.session_state["driver_analysis_player"] = player_name
    if destination:
        st.session_state.dashboard_navigation_page = destination


def render_command_palette_results(results: pd.DataFrame) -> None:
    """Render compact command-palette rows with scouting previews and quick actions."""
    if results is None or results.empty:
        st.markdown(
            f"<div class='tm69-command-empty'>{html.escape('Sin resultados relevantes' if LANG != 'EN' else 'No relevant results')}</div>",
            unsafe_allow_html=True,
        )
        return

    top_player = results[results["entity_type"].astype(str) == "player"].head(1)
    if not top_player.empty:
        r0 = top_player.iloc[0]
        insight_bits = []
        opp_txt = _format_command_score(r0.get("opportunity"))
        risk_txt = _format_command_score(r0.get("risk"))
        gap_txt = _format_command_pct(r0.get("gap_pct"))
        mv_txt = format_money_short(r0.get("market_value"))
        fv_txt = format_money_short(r0.get("fair_value"))
        if opp_txt != "N/A":
            insight_bits.append(f"Opportunity {opp_txt}/100")
        if gap_txt != "N/A":
            insight_bits.append(f"Gap {gap_txt}")
        if risk_txt != "N/A":
            insight_bits.append(f"Risk {risk_txt}/100")
        if mv_txt != "N/A" and fv_txt != "N/A":
            insight_bits.append(f"TM {mv_txt} vs IQ {fv_txt}")
        insight = " · ".join(insight_bits[:4])
        st.markdown(
            f"""
<div class="tm69-ai-insight">
    <span>{html.escape('AI Scouting Snapshot' if LANG == 'EN' else 'Scouting IQ Insight')}</span>
    <b>{html.escape(str(r0.get('raw', '')))}</b>
    <small>{html.escape(insight)}</small>
</div>
""",
            unsafe_allow_html=True,
        )

    st.markdown('<div class="tm69-command-list">', unsafe_allow_html=True)
    for i, (_, row) in enumerate(results.iterrows()):
        label = str(row.get("label", ""))
        raw = str(row.get("raw", ""))
        entity = str(row.get("entity_type", "entity"))
        entity_label = {"player": "Jugador", "club": "Club", "league": "Liga", "position": "Posición", "role": "Rol"}.get(entity, "Entidad") if LANG != "EN" else entity.title()
        club = str(row.get("club", "") or "")
        league = str(row.get("league", "") or "")
        position = str(row.get("position", "") or "")
        age = row.get("age", np.nan)
        age_txt = ""
        try:
            age_txt = f"{float(age):.0f} años" if LANG != "EN" and pd.notna(age) else (f"{float(age):.0f} yrs" if pd.notna(age) else "")
        except Exception:
            age_txt = ""
        meta = " · ".join([x for x in [club, league, position, age_txt] if str(x).strip()]) or entity_label
        opp = _format_command_score(row.get("opportunity"))
        risk = _format_command_score(row.get("risk"))
        contract = _format_command_score(row.get("contract"))
        gap = _format_command_pct(row.get("gap_pct"))
        market_value = format_money_short(row.get("market_value"))
        fair_value = format_money_short(row.get("fair_value"))
        score = _format_command_score(row.get("typeahead_score"))
        rank = row.get("rank", np.nan)
        try:
            rank_txt = f"#{int(float(rank))}" if pd.notna(rank) else f"#{i+1}"
        except Exception:
            rank_txt = f"#{i+1}"

        st.markdown(
            f"""
<div class="tm69-command-row">
    <div class="tm69-command-rank">{html.escape(rank_txt)}</div>
    <div class="tm69-command-main">
        <div class="tm69-command-name">{html.escape(raw)}</div>
        <div class="tm69-command-meta">{html.escape(meta)}</div>
    </div>
    <div class="tm69-command-signals">
        <span><small>Opp</small><b>{html.escape(opp)}</b></span>
        <span><small>Gap</small><b>{html.escape(gap)}</b></span>
        <span><small>Risk</small><b>{html.escape(risk)}</b></span>
        <span><small>Contract</small><b>{html.escape(contract)}</b></span>
        <span><small>Value</small><b>{html.escape(market_value)}</b></span>
        <span><small>IQ</small><b>{html.escape(fair_value)}</b></span>
    </div>
    <div class="tm69-command-score"><small>DSS</small><b>{html.escape(score)}</b></div>
</div>
""",
            unsafe_allow_html=True,
        )
        if entity == "player":
            action_cols = st.columns([0.18, 0.18, 0.20, 0.20, 0.24], gap="small")
            with action_cols[0]:
                if st.button("Perfil" if LANG != "EN" else "Profile", key=f"tm69_cmd_profile_{i}_{abs(hash(label))}"):
                    st.session_state["global_scouting_search"] = label
                    st.session_state["global_scouting_selected_label"] = label
                    _command_set_player_context(raw, "Player Intelligence")
                    st.rerun()
            with action_cols[1]:
                if st.button("Comparar" if LANG != "EN" else "Compare", key=f"tm69_cmd_compare_{i}_{abs(hash(label))}"):
                    st.session_state["global_scouting_search"] = label
                    st.session_state["global_scouting_selected_label"] = label
                    _command_set_player_context(raw, "Player Intelligence")
                    st.session_state["selected_module"] = "Comparables"
                    st.rerun()
            with action_cols[2]:
                if st.button("Recruitment", key=f"tm69_cmd_recruit_{i}_{abs(hash(label))}"):
                    st.session_state["global_scouting_search"] = label
                    st.session_state["global_scouting_selected_label"] = label
                    _command_set_player_context(raw, "Recruitment Intelligence")
                    st.rerun()
            with action_cols[3]:
                if st.button("Contrato" if LANG != "EN" else "Contract", key=f"tm69_cmd_contract_{i}_{abs(hash(label))}"):
                    st.session_state["global_scouting_search"] = label
                    st.session_state["global_scouting_selected_label"] = label
                    _command_set_player_context(raw, "Strategy Center")
                    st.session_state["strategy_center_view"] = "Contract Intelligence"
                    st.rerun()
            with action_cols[4]:
                if st.button("Abrir" if LANG != "EN" else "Open", key=f"tm69_cmd_open_{i}_{abs(hash(label))}"):
                    st.session_state["global_scouting_search"] = label
                    st.session_state["global_scouting_selected_label"] = label
                    _command_set_player_context(raw, None)
                    st.rerun()
        else:
            if st.button("Aplicar filtro" if LANG != "EN" else "Apply filter", key=f"tm69_cmd_apply_{i}_{abs(hash(label))}"):
                st.session_state["global_scouting_search"] = label
                st.session_state["global_scouting_selected_label"] = label
                st.rerun()
    st.markdown('</div>', unsafe_allow_html=True)

def render_action_badge(label: str) -> str:
    """Modern action badges for the recruitment ranking."""
    raw = str(label)
    display = action_display_name(raw) if "action_display_name" in globals() else V(raw)
    if raw in {"Iniciar contacto", "Due diligence"}:
        cls, icon = "action-badge-green", "🟢"
    elif raw in {"Vídeo scouting", "Seguimiento activo", "Analizar en vídeo"}:
        cls, icon = "action-badge-yellow", "🟡"
    elif raw in {"Monitorización pasiva", "No priorizar", "Descartar por riesgo"}:
        cls, icon = "action-badge-red", "🔴"
    else:
        cls, icon = "action-badge-gray", "⚪"
    return f'<span class="{cls}">{icon} {html.escape(display)}</span>'




