# CRM-style autocomplete search. Labels show entity type, while filtering keeps the raw value.
# TM.6.9C: search state is resolved before filters, but the visual Command Center
# is rendered after active filters are computed so the context panel stays inside
# the same horizontal header.
search_options, search_label_to_raw = build_search_options(football_df)

current_global_search = st.session_state.get("global_scouting_search")
if current_global_search is not None and str(current_global_search) not in search_options:
    st.session_state["global_scouting_search"] = None

query_value_state = str(st.session_state.get("global_scouting_query", "") or "")
selected_from_session = st.session_state.get("global_scouting_search")
if selected_from_session in search_label_to_raw:
    candidate_results = pd.DataFrame()
    global_search_label = selected_from_session
else:
    candidate_results = rank_global_command_search(football_df, query_value_state, search_options, search_label_to_raw, max_results=5)

if selected_from_session in search_label_to_raw:
    global_search_label = selected_from_session
elif str(query_value_state).strip() and candidate_results is not None and not candidate_results.empty:
    # Typeahead auto-resolves to the top ranked entity. This preserves the old
    # functional behaviour without using Streamlit selectbox/dropdown components.
    global_search_label = str(candidate_results.iloc[0].get("label", ""))
else:
    global_search_label = None

global_search_query = "" if global_search_label is None else search_label_to_raw.get(str(global_search_label), str(global_search_label))
global_search_display = "" if global_search_label is None else str(global_search_label)


# Search can target the wider football dataset, but only Scouting Universe results
# are allowed to drive ranking, shortlist, Opportunity/Risk matrix and executive cards.
search_entity_type = ""
search_entity_type = _command_entity_type(global_search_display)

search_norm = normalize_search_text(global_search_query)
scouting_name_col = get_player_name_column(scouting_df)
football_name_col = get_player_name_column(football_df)
search_matches_scouting_universe = False
search_is_outside_scouting_player = False
outside_football_profile = pd.DataFrame()

if search_norm and search_entity_type == "player":
    if scouting_name_col is not None and scouting_name_col in scouting_df.columns:
        scouting_names_norm = scouting_df[scouting_name_col].dropna().astype(str).map(normalize_search_text)
        search_matches_scouting_universe = bool((scouting_names_norm == search_norm).any())
    if not search_matches_scouting_universe:
        outside_name_candidates = [
            "player_name_tm",
            "player_name_fbref",
            "player_name",
            "player",
            "name",
        ]
        outside_mask = pd.Series(False, index=football_df.index)
        for outside_name_col in outside_name_candidates:
            if outside_name_col in football_df.columns:
                outside_mask = outside_mask | (
                    football_df[outside_name_col]
                    .fillna("")
                    .astype(str)
                    .map(normalize_search_text)
                    .eq(search_norm)
                )
        outside_football_profile = football_df[outside_mask].head(1).copy()
        if not outside_football_profile.empty:
            # Normalize outside-scouting profile aliases for the fallback card.
            alias_map = {
                "player_name_tm": "player_name",
                "player_name_fbref": "player_name",
                "club": "current_club",
                "team": "current_club",
                "league": "current_league",
                "position_group": "position",
                "position": "position_group",
                "age": "current_age",
                "minutes_played": "current_minutes_played",
                "minutes": "current_minutes_played",
                "market_value_eur": "current_market_value_eur",
                "market_value_eur": "market_value_eur",
                "confidence_score": "confidence_score",
                "opportunity_score": "opportunity_score",
                "risk_score": "risk_score",
            }
            for src_col, dst_col in alias_map.items():
                if src_col in outside_football_profile.columns:
                    if dst_col not in outside_football_profile.columns:
                        outside_football_profile[dst_col] = outside_football_profile[src_col]
                    else:
                        src_values = outside_football_profile[src_col]
                        dst_values = outside_football_profile[dst_col]
                        try:
                            fill_mask = dst_values.isna() | dst_values.astype(str).str.strip().isin(["", "nan", "None", "N/A"])
                            outside_football_profile.loc[fill_mask, dst_col] = src_values[fill_mask]
                        except Exception:
                            pass
        if not outside_football_profile.empty:
            # Enrich outside-scouting informational profiles with productive panel fields
            # when the current snapshot lacks club, age or minutes.
            try:
                panel_path = PROCESSED_PATH / "player_season_modeling_v13b_productive_candidate.parquet"
                if panel_path.exists():
                    panel_cols = [
                        "player_id_tm",
                        "player_name_tm",
                        "player_name_fbref",
                        "club",
                        "league",
                        "age",
                        "minutes_played",
                        "market_value_eur",
                        "position_group",
                        "position",
                    ]
                    try:
                        import pyarrow.parquet as pq
                        available_cols = set(pq.ParquetFile(panel_path).schema.names)
                        panel = pd.read_parquet(
                            panel_path,
                            columns=[c for c in panel_cols if c in available_cols],
                        )
                    except Exception:
                        panel = pd.read_parquet(panel_path)
                        panel = panel[[c for c in panel_cols if c in panel.columns]].copy()
                    panel["_outside_key_name_tm"] = panel.get("player_name_tm", "").fillna("").astype(str).map(normalize_search_text)
                    panel["_outside_key_name_fbref"] = panel.get("player_name_fbref", "").fillna("").astype(str).map(normalize_search_text)

                    outside_name_key = normalize_search_text(
                        outside_football_profile.iloc[0].get("player_name_tm", outside_football_profile.iloc[0].get("player_name", ""))
                    )
                    panel_match = panel[
                        (panel["_outside_key_name_tm"] == outside_name_key)
                        | (panel["_outside_key_name_fbref"] == outside_name_key)
                    ].copy()

                    if not panel_match.empty:
                        if "minutes_played" in panel_match.columns:
                            panel_match = panel_match.sort_values("minutes_played", ascending=False, na_position="last")
                        enrich_row = panel_match.iloc[0]
                        enrich_map = {
                            "club": "current_club",
                            "league": "current_league",
                            "age": "current_age",
                            "minutes_played": "current_minutes_played",
                            "market_value_eur": "current_market_value_eur",
                            "position_group": "position_group",
                            "position": "position",
                        }
                        for src_col, dst_col in enrich_map.items():
                            if src_col in enrich_row.index:
                                val = enrich_row.get(src_col)
                                if pd.notna(val) and str(val).strip() not in {"", "nan", "None", "N/A"}:
                                    if dst_col not in outside_football_profile.columns:
                                        outside_football_profile[dst_col] = val
                                    else:
                                        cur = outside_football_profile.iloc[0].get(dst_col)
                                        if pd.isna(cur) or str(cur).strip() in {"", "nan", "None", "N/A"}:
                                            outside_football_profile.loc[outside_football_profile.index[0], dst_col] = val
                                    if src_col not in outside_football_profile.columns:
                                        outside_football_profile[src_col] = val
                                    else:
                                        cur2 = outside_football_profile.iloc[0].get(src_col)
                                        if pd.isna(cur2) or str(cur2).strip() in {"", "nan", "None", "N/A"}:
                                            outside_football_profile.loc[outside_football_profile.index[0], src_col] = val
            except Exception as exc:
                print(f"[TM6.10 outside profile enrichment skipped] {exc}")

        if not outside_football_profile.empty:
            try:
                projected = add_projected_market_value_features(outside_football_profile.copy())
                for col in [
                    "projected_market_value_3y_eur",
                    "asset_upside_3y_eur",
                    "projected_value_multiplier_3y",
                    "asset_roi_3y_pct",
                    "future_asset_score",
                ]:
                    if col in projected.columns:
                        outside_football_profile[col] = projected[col]
            except Exception as exc:
                print(f"[TM6.10 outside profile projection skipped] {exc}")

        if not outside_football_profile.empty:
            outside_football_profile = tm71_select_latest_analytics_row(outside_football_profile)
            outside_football_profile = tm71_build_presentation_df(outside_football_profile)

        search_is_outside_scouting_player = not outside_football_profile.empty



@st.cache_data(show_spinner=False)
def tm71_load_full_modeling_analytics():
    """Load full modeling dataset for latest player-season analytics lookup."""
    try:
        path = PROCESSED_PATH / "player_season_modeling_v13a.parquet"
        if path.exists():
            return pd.read_parquet(path)
    except Exception as exc:
        print(f"[TM.7.2 full modeling analytics load failed] {exc}")
    return pd.DataFrame()



def tm71_latest_player_dss_metrics_from_full(player_id_tm):
    """Return latest row with DSS-derived metrics for a player."""
    full = tm71_load_full_modeling_analytics()
    if full.empty or "player_id_tm" not in full.columns:
        return pd.Series(dtype="object")

    try:
        pid = int(float(player_id_tm))
    except Exception:
        return pd.Series(dtype="object")

    player_ids = pd.to_numeric(full["player_id_tm"], errors="coerce")
    rows = full[player_ids == pid].copy()
    if rows.empty:
        return pd.Series(dtype="object")

    dss_cols = [
        "opportunity_score",
        "confidence_score",
        "risk_score",
        "asset_roi_3y_pct",
        "predicted_market_value_eur",
        "market_value_gap_eur",
    ]
    existing = [c for c in dss_cols if c in rows.columns]
    if not existing:
        return pd.Series(dtype="object")

    # DSS row must contain model-derived opportunity/risk/ROI, not only raw matching confidence.
    priority_cols = [c for c in ["opportunity_score", "risk_score", "asset_roi_3y_pct"] if c in rows.columns]
    if priority_cols:
        mask = rows[priority_cols].notna().any(axis=1)
    else:
        mask = rows[existing].notna().any(axis=1)
    rows = rows[mask].copy()
    if rows.empty:
        return pd.Series(dtype="object")

    if "valuation_date" in rows.columns:
        rows["_tm71_dss_date_sort"] = pd.to_datetime(rows["valuation_date"], errors="coerce")
    else:
        rows["_tm71_dss_date_sort"] = pd.NaT

    if "season" in rows.columns:
        rows["_tm71_dss_season_sort"] = pd.to_numeric(
            rows["season"].astype(str).str.extract(r"(\\d{4})")[0],
            errors="coerce",
        )
    else:
        rows["_tm71_dss_season_sort"] = np.nan

    rows = rows.sort_values(
        ["_tm71_dss_date_sort", "_tm71_dss_season_sort"],
        ascending=[False, False],
    )

    return rows.iloc[0]



def tm71_latest_player_analytics_from_full(player_id_tm):
    """Return latest analytical row for a player from full modeling dataset."""
    full = tm71_load_full_modeling_analytics()
    if full.empty or "player_id_tm" not in full.columns:
        return pd.DataFrame()

    try:
        pid = int(float(player_id_tm))
    except Exception:
        return pd.DataFrame()

    player_ids = pd.to_numeric(full["player_id_tm"], errors="coerce")
    rows = full[player_ids == pid].copy()

    if rows.empty:
        return pd.DataFrame()

    if "valuation_date" in rows.columns:
        rows["_tm71_date_sort"] = pd.to_datetime(rows["valuation_date"], errors="coerce")
    else:
        rows["_tm71_date_sort"] = pd.NaT

    if "season_start_year" in rows.columns:
        rows["_tm71_season_sort"] = pd.to_numeric(rows["season_start_year"], errors="coerce")
    elif "season" in rows.columns:
        rows["_tm71_season_sort"] = pd.to_numeric(
            rows["season"].astype(str).str.extract(r"(\\d{4})")[0],
            errors="coerce",
        )
    else:
        rows["_tm71_season_sort"] = np.nan

    rows["_tm71_minutes_sort"] = (
        pd.to_numeric(rows["minutes_played"], errors="coerce")
        if "minutes_played" in rows.columns
        else 0
    )

    rows = rows.sort_values(
        ["_tm71_date_sort", "_tm71_season_sort", "_tm71_minutes_sort"],
        ascending=[False, False, False],
    )

    return rows.head(1).drop(
        columns=[c for c in ["_tm71_date_sort", "_tm71_season_sort", "_tm71_minutes_sort"] if c in rows.columns]
    )




@st.cache_data(show_spinner=False)
def tm72_load_dss_authority():
    """Load DSS-derived metrics authority."""
    try:
        path = ROOT / "reports" / "dss" / "global_prospect_universe.csv"
        if path.exists():
            return pd.read_csv(path)
    except Exception as exc:
        print(f"[TM.7.2 DSS authority load failed] {exc}")
    return pd.DataFrame()


def tm72_latest_player_dss_metrics(player_id_tm):
    """Return DSS-derived metrics for a player from DSS Authority."""
    dss = tm72_load_dss_authority()
    if dss.empty or "player_id_tm" not in dss.columns:
        return pd.Series(dtype="object")

    try:
        pid = int(float(player_id_tm))
    except Exception:
        return pd.Series(dtype="object")

    rows = dss[pd.to_numeric(dss["player_id_tm"], errors="coerce") == pid].copy()
    if rows.empty:
        return pd.Series(dtype="object")

    sort_cols = []
    if "opportunity_score" in rows.columns:
        rows["_tm72_opp_sort"] = pd.to_numeric(rows["opportunity_score"], errors="coerce")
        sort_cols.append("_tm72_opp_sort")
    if "confidence_score" in rows.columns:
        rows["_tm72_conf_sort"] = pd.to_numeric(rows["confidence_score"], errors="coerce")
        sort_cols.append("_tm72_conf_sort")

    if sort_cols:
        rows = rows.sort_values(sort_cols, ascending=[False] * len(sort_cols))

    return rows.iloc[0]


